sys_script_include.script:
var PulseBoxAIAB = Class.create();
PulseBoxAIAB.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    /**
     * Get pending reviews for a record (called from client script)
     * Supports both old single-field and new multi-field formats
     * @returns {string} JSON array of reviews
     */
    getPendingSuggestions: function() {
        var targetTable = this.getParameter('sysparm_target_table');
        var targetSysId = this.getParameter('sysparm_target_sys_id');

        if (!targetTable || !targetSysId) {
            return JSON.stringify([]);
        }

        var suggestions = [];
        var gr = new GlideRecord('u_ai_file');
        gr.addQuery('u_target_table', targetTable);
        gr.addQuery('u_target_sys_id', targetSysId);
        gr.addQuery('u_status', 'pending');
        gr.orderByDesc('sys_created_on');
        gr.query();

        while (gr.next()) {
            var changes = '' + gr.getValue('u_changes');
            var isMultiField = changes && changes.length > 0;

            suggestions.push({
                sys_id: gr.getUniqueValue(),
                is_multi_field: isMultiField,
                field_name: '' + gr.getValue('u_field_name'),
                explanation: '' + gr.getValue('u_explanation'),
                suggested_content: '' + gr.getValue('u_suggested_content'),
                changes: isMultiField ? changes : null,
                agent_name: gr.u_agent.getDisplayValue()
            });
        }

        return JSON.stringify(suggestions);
    },

    /**
     * Get full details for a review including current field content
     * Supports both old single-field and new multi-field formats
     * @returns {string} JSON object with review details and current content
     */    /**
     * Retrieves suggestion details based on the provided suggestion ID.
     * @returns {String} JSON string with suggestion details or error message.
     */
    getSuggestionDetails: function() {
        var suggestionId = this.getParameter('sysparm_suggestion_id');
        if (!suggestionId) {
            return JSON.stringify({ error: 'No suggestion ID provided' });
        }

        var fileGR = new GlideRecord('u_ai_file');
        if (!fileGR.get(suggestionId)) {
            return JSON.stringify({ error: 'Suggestion not found' });
        }

        var targetTable = '' + fileGR.u_target_table;
        var targetSysId = '' + fileGR.u_target_sys_id;
        var changes = '' + fileGR.getValue('u_changes');
        var isMultiField = changes && changes.length > 0;

        // Get current values from target record
        var currentValues = {};
        var fieldNameVal = '' + fileGR.getValue('u_field_name');
        var targetGR = new GlideRecord(targetTable);
        if (!targetGR.get(targetSysId)) {
            return JSON.stringify({
                sys_id: fileGR.getUniqueValue(),
                is_multi_field: isMultiField,
                field_name: '' + fileGR.getValue('u_field_name'),
                explanation: '' + fileGR.getValue('u_explanation'),
                suggested_content: '' + fileGR.getValue('u_suggested_content'),
                changes: isMultiField ? changes : null,
                current_values: currentValues,
                agent_name: fileGR.u_agent.getDisplayValue(),
                target_table: targetTable,
                target_sys_id: targetSysId
            });
        }

        if (fieldNameVal.indexOf('script:') === 0) {
            // Function-level: extract just the current function body
            var funcName = fieldNameVal.split(':')[1];
            var script = '' + targetGR.getValue('script');
            var funcs = this.extractFunctions(script);
            for (var fi = 0; fi < funcs.length; fi++) {
                if (funcs[fi].name === funcName) {
                    currentValues[funcName] = funcs[fi].body;
                    break;
                }
            }
        } else if (isMultiField) {
            // Multi-field: get current value for each changed field
            try {
                var changesObj = JSON.parse(changes);
                for (var field in changesObj) {
                    if (changesObj.hasOwnProperty(field)) {
                        currentValues[field] = '' + targetGR.getValue(field);
                    }
                }
            } catch (e) {
                gs.error('PulseBox: Error parsing changes JSON: ' + e);
            }
        } else {
            // Single-field (legacy)
            var fieldName = '' + fileGR.u_field_name;
            if (fieldName) {
                currentValues[fieldName] = '' + targetGR.getValue(fieldName);
            }
        }

        return JSON.stringify({
            sys_id: fileGR.getUniqueValue(),
            is_multi_field: isMultiField,
            field_name: '' + fileGR.getValue('u_field_name'),
            explanation: '' + fileGR.getValue('u_explanation'),
            suggested_content: '' + fileGR.getValue('u_suggested_content'),
            changes: isMultiField ? changes : null,
            current_values: currentValues,
            agent_name: fileGR.u_agent.getDisplayValue(),
            target_table: targetTable,
            target_sys_id: targetSysId
        });
    },

    /**
     * Apply a review - handles field-level, function-level, and legacy formats
     * @returns {string} JSON with success/error
     */    /**
     * Applies a review based on the given suggestion ID.
     *
     * @returns {string} A JSON string indicating success or error.
     */
    applyReview: function() {
        var reviewId = this.getParameter('sysparm_suggestion_id');
        if (!reviewId) {
            return JSON.stringify({ error: 'No review ID provided' });
        }

        var fileGR = new GlideRecord('u_ai_file');
        if (!fileGR.get(reviewId)) {
            return JSON.stringify({ error: 'Review not found' });
        }

        if (fileGR.u_status != 'pending') {
            return JSON.stringify({ error: 'Review already ' + fileGR.u_status });
        }

        var targetTable = '' + fileGR.u_target_table;
        var targetSysId = '' + fileGR.u_target_sys_id;
        var changes = '' + fileGR.getValue('u_changes');
        var isMultiField = changes && changes.length > 0;
        var fieldName = '' + fileGR.getValue('u_field_name');

        // Get target record
        var targetGR = new GlideRecord(targetTable);
        if (!targetGR.get(targetSysId)) {
            return JSON.stringify({ error: 'Target record not found' });
        }

        var fieldsUpdated = [];
        var originalValues = {};

        if (isMultiField && fieldName.indexOf('script:') === 0) {
            // Single-function change: field_name is "script:functionName"
            var targetFuncName = fieldName.split(':')[1];
            try {
                var changesObj = JSON.parse(changes);
                var script = '' + targetGR.getValue('script');
                originalValues.script = script;
                // Get the suggested replacement — key is the function name
                var suggested = changesObj[targetFuncName] ? changesObj[targetFuncName].suggested : null;
                if (!suggested) {
                    return JSON.stringify({ error: 'No suggested change found for function ' + targetFuncName });
                }

                // Find the original function in the script using indexOf (no regex needed)
                var sigIdx = script.indexOf(targetFuncName + ': function(');
                if (sigIdx < 0) sigIdx = script.indexOf(targetFuncName + ': function (');
                if (sigIdx < 0) {
                    return JSON.stringify({ error: 'Function ' + targetFuncName + ' not found in script' });
                }
                // Walk back to include leading whitespace
                var startIdx = sigIdx;
                while (startIdx > 0 && script[startIdx - 1] === ' ') startIdx--;
                var braceDepth = 0;
                var endIdx = startIdx;
                var foundOpen = false;
                for (var ci = startIdx; ci < script.length; ci++) {
                    if (script[ci] === '{') { braceDepth++; foundOpen = true; }
                    if (script[ci] === '}') braceDepth--;
                    if (foundOpen && braceDepth === 0) {
                        endIdx = ci + 1;
                        if (ci + 1 < script.length && script[ci + 1] === ',') endIdx = ci + 2;
                        break;
                    }
                }

                var originalFunc = script.substring(startIdx, endIdx);
                script = script.replace(originalFunc, suggested);
                targetGR.setValue('script', script);
                fieldsUpdated.push('script');
            } catch (e) {
                return JSON.stringify({ error: 'Failed to apply function change: ' + e });
            }
        } else if (isMultiField) {
            // Field-level changes (original multi-field format)
            try {
                var changesObj2 = JSON.parse(changes);
                for (var field in changesObj2) {
                    if (changesObj2.hasOwnProperty(field) && changesObj2[field].suggested) {
                        originalValues[field] = '' + targetGR.getValue(field);
                        targetGR.setValue(field, changesObj2[field].suggested);
                        fieldsUpdated.push(field);
                    }
                }
            } catch (e) {
                return JSON.stringify({ error: 'Failed to parse changes: ' + e });
            }
        } else {
            // Legacy single-field format
            var legacyField = '' + fileGR.u_field_name;
            var suggestedContent = '' + fileGR.u_suggested_content;
            if (!legacyField || !suggestedContent) {
                return JSON.stringify({ error: 'No legacy field or content provided' });
            }
            originalValues[legacyField] = '' + targetGR.getValue(legacyField);
            targetGR.setValue(legacyField, suggestedContent);
            fieldsUpdated.push(legacyField);
        }

        if (fieldsUpdated.length === 0) {
            return JSON.stringify({ error: 'No changes to apply' });
        }

        // Save original values for potential rollback
        fileGR.u_original_content = JSON.stringify(originalValues);

        // Apply changes
        var updated = targetGR.update();
        if (!updated) {
            return JSON.stringify({ error: 'Failed to update target record' });
        }

        // Mark review as accepted
        fileGR.u_status = 'accepted';
        fileGR.update();

        gs.info('PulseBox: Applied review ' + reviewId + ', updated fields: ' + fieldsUpdated.join(', '));
        return JSON.stringify({ 
            success: true, 
            fields_updated: fieldsUpdated,
            message: 'Updated ' + fieldsUpdated.length + ' field(s): ' + fieldsUpdated.join(', ')
        });
    },

    /**
     * Reject a review
     * @returns {string} JSON success or error
     */
    rejectSuggestion: function() {
        var suggestionId = this.getParameter('sysparm_suggestion_id');
        if (!suggestionId) {
            return JSON.stringify({ error: 'No suggestion ID provided' });
        }

        var fileGR = new GlideRecord('u_ai_file');
        if (!fileGR.get(suggestionId)) {
            return JSON.stringify({ error: 'Suggestion not found' });
        }

        fileGR.u_status = 'rejected';
        fileGR.update();

        gs.info('PulseBox: Rejected suggestion ' + suggestionId);
        return JSON.stringify({ success: true });
    },

    /**
     * Run heartbeat for all active agents. Also cancels stale inferences (>60s).
     * @returns {object} summary of processed, skipped, and errors
     */
    runHeartbeat: function() {
        // Cancel stale pulsebox inferences older than 60 seconds
        this.cancelStaleInferences(60);

        var summary = { processed: 0, skipped: 0, errors: 0, agents: [] };
        var agentGR = new GlideRecord('u_ai_agent');
        agentGR.addQuery('u_active', true);
        agentGR.query();

        while (agentGR.next()) {
            var agentName = '' + agentGR.u_name;
            var heartbeatMinutes = parseInt(agentGR.u_heartbeat_minutes) || 60;
            var lastHeartbeat = agentGR.u_last_heartbeat ? new GlideDateTime(agentGR.u_last_heartbeat) : null;
            var now = new GlideDateTime();

            if (lastHeartbeat) {
                var diff = gs.dateDiff(lastHeartbeat.getValue(), now.getValue(), true);
                var minutesSince = Math.floor(parseInt(diff) / 60);
                if (minutesSince < heartbeatMinutes) {
                    summary.skipped++;
                    continue;
                }
            }

            try {
                var result = this.processAgent(agentGR);
                summary.agents.push({ name: agentName, recordsFound: result.recordsFound, inferencesCreated: result.inferencesCreated });
                summary.processed++;
                agentGR.u_last_heartbeat = now;
                agentGR.update();
            } catch (e) {
                gs.error('PulseBox: Error processing agent ' + agentName + ': ' + e);
                summary.errors++;
            }
        }
        return summary;
    },

    /**
     * Cancel pulsebox inferences stuck in new/requested for longer than maxSeconds
     * @param {number} maxSeconds - Max age in seconds before cancelling
     */
    cancelStaleInferences: function(maxSeconds) {
        var cutoff = new GlideDateTime();
        cutoff.addSeconds(-maxSeconds);
        var gr = new GlideRecord('u_ai_inference');
        gr.addQuery('u_type', 'pulsebox');
        gr.addQuery('u_state', 'IN', 'new,requested');
        gr.addQuery('sys_created_on', '<', cutoff.getValue());
        gr.query();
        while (gr.next()) {
            gs.warn('PulseBox: Cancelling stale inference ' + gr.getUniqueValue() + ' (age > ' + maxSeconds + 's)');
            gr.u_state = 'cancelled';
            gr.update();
        }
    },

    /**
     * Process a single agent - for script tables, creates one inference per function (max 3 per heartbeat)
     * @param {GlideRecord} agentGR - The agent record
     * @returns {object} - { recordsFound, inferencesCreated }
     */
    processAgent: function(agentGR) {
        var result = { recordsFound: 0, inferencesCreated: 0 };
        var targetTable = '' + agentGR.u_target_table;
        var filter = '' + agentGR.u_filter;
        var maxInferences = 3;
        if (!targetTable) return result;

        var isScriptTable = (targetTable === 'sys_script_include' || targetTable === 'sys_script');
        var targetGR = new GlideRecord(targetTable);
        if (filter) targetGR.addEncodedQuery(filter);
        targetGR.query();

        while (targetGR.next() && result.inferencesCreated < maxInferences) {
            result.recordsFound++;
            var recordSysId = targetGR.getUniqueValue();

            // Check if inference already in progress for this record
            var existingInf = new GlideRecord('u_ai_inference');
            existingInf.addQuery('u_type', 'pulsebox');
            existingInf.addQuery('u_table', targetTable);
            existingInf.addQuery('u_target', recordSysId);
            existingInf.addQuery('u_state', 'IN', 'new,requested');
            existingInf.setLimit(1);
            existingInf.query();
            if (existingInf.hasNext()) continue;

            if (isScriptTable) {
                // Split script into functions and create one inference per function
                var script = '' + targetGR.getValue('script');
                var funcs = this.extractFunctions(script);
                var scriptName = '' + targetGR.getValue('name');
                for (var fi = 0; fi < funcs.length && result.inferencesCreated < maxInferences; fi++) {
                    var func = funcs[fi];
                    // Check if this function already has a pending review
                    var existingFuncFile = new GlideRecord('u_ai_file');
                    existingFuncFile.addQuery('u_agent', agentGR.getUniqueValue());
                    existingFuncFile.addQuery('u_target_sys_id', recordSysId);
                    existingFuncFile.addQuery('u_status', 'pending');
                    existingFuncFile.addQuery('u_field_name', 'script:' + func.name);
                    existingFuncFile.setLimit(1);
                    existingFuncFile.query();
                    if (existingFuncFile.hasNext()) continue;

                    var inferenceId = this.createFunctionInference(agentGR, targetGR, func, scriptName);
                    if (inferenceId) result.inferencesCreated++;
                }
            } else {
                // Non-script tables: one inference per record (original behavior)
                var existingFile = new GlideRecord('u_ai_file');
                existingFile.addQuery('u_agent', agentGR.getUniqueValue());
                existingFile.addQuery('u_target_table', targetTable);
                existingFile.addQuery('u_target_sys_id', recordSysId);
                existingFile.addQuery('u_status', 'pending');
                existingFile.setLimit(1);
                existingFile.query();
                if (existingFile.hasNext()) continue;

                var infId = this.createInference(agentGR, targetGR);
                if (infId) result.inferencesCreated++;
            }
        }
        if (result.inferencesCreated > 0) {
            gs.info('PulseBox: Created ' + result.inferencesCreated + ' inference(s) for agent ' + agentGR.u_name);
        }
        return result;
    },

    /**
     * Create an inference for the agent to analyze a record
     */
    createInference: function(agentGR, targetGR) {
        var agentId = agentGR.getUniqueValue();
        var systemPrompt = '' + agentGR.u_system_prompt;
        var model = '' + agentGR.u_model || 'gpt-4o-mini';
        var targetTable = '' + agentGR.u_target_table;
        var recordContext = this.buildRecordContext(targetGR, targetTable);

        var messages = [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: 'Analyze this record:\n\n' + recordContext }
        ];

        var inferenceGR = new GlideRecord('u_ai_inference');
        inferenceGR.initialize();
        inferenceGR.u_prompt = JSON.stringify(messages);
        inferenceGR.u_type = 'pulsebox';
        inferenceGR.u_state = 'new';
        inferenceGR.u_model = model;
        inferenceGR.u_table = targetTable;
        inferenceGR.u_target = targetGR.getUniqueValue();
        inferenceGR.u_requested_by = gs.getUserID();
        inferenceGR.u_metadata = JSON.stringify({ agent_id: agentId });
        return inferenceGR.insert();
    },

    /**
     * Extract individual functions from a Class.create() style script
     * @param {string} script - Full script content
     * @returns {Array} - [{name, body}] for each function found
     */
    extractFunctions: function(script) {
        var functions = [];
        // Match "functionName: function(" patterns typical of Class.create()
        var pattern = /(\w+)\s*:\s*function\s*\(/g;
        var match;
        while ((match = pattern.exec(script)) !== null) {
            var funcName = match[1];
            // Skip 'type' property and 'initialize' if empty
            if (funcName === 'type') continue;

            var startIdx = match.index;
            // Find the full function body using brace counting
            var braceDepth = 0;
            var foundOpen = false;
            var endIdx = startIdx;
            for (var ci = startIdx; ci < script.length; ci++) {
                if (script[ci] === '{') { braceDepth++; foundOpen = true; }
                if (script[ci] === '}') braceDepth--;
                if (foundOpen && braceDepth === 0) {
                    endIdx = ci + 1;
                    if (ci + 1 < script.length && script[ci + 1] === ',') endIdx = ci + 2;
                    break;
                }
            }
            var body = script.substring(startIdx, endIdx);
            // Skip trivially small functions (< 100 chars, e.g. empty initialize)
            if (body.length < 100) continue;
            functions.push({ name: funcName, body: body });
        }
        return functions;
    },

    /**
     * Create an inference for a single function within a script
     * @param {GlideRecord} agentGR - Agent record
     * @param {GlideRecord} targetGR - Target script include/business rule record
     * @param {object} func - {name, body} of the function to review
     * @param {string} scriptName - Name of the script include
     * @returns {string} - sys_id of created inference, or null
     */
    createFunctionInference: function(agentGR, targetGR, func, scriptName) {
        var agentId = agentGR.getUniqueValue();
        var systemPrompt = '' + agentGR.u_system_prompt;
        var model = '' + agentGR.u_model || 'gpt-4o-mini';
        var targetTable = '' + agentGR.u_target_table;

        var context = 'Script Include: ' + scriptName + '\n';
        context += 'Function: ' + func.name + '\n\n';
        context += func.body;

        var messages = [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: 'Review this function:\n\n' + context }
        ];

        var inferenceGR = new GlideRecord('u_ai_inference');
        inferenceGR.initialize();
        inferenceGR.u_prompt = JSON.stringify(messages);
        inferenceGR.u_type = 'pulsebox';
        inferenceGR.u_state = 'new';
        inferenceGR.u_model = model;
        inferenceGR.u_table = targetTable;
        inferenceGR.u_target = targetGR.getUniqueValue();
        inferenceGR.u_requested_by = gs.getUserID();
        inferenceGR.u_metadata = JSON.stringify({ agent_id: agentId, function_name: func.name });
        return inferenceGR.insert();
    },

    /**
     * Process a completed pulsebox inference - creates u_ai_file review record
     * Handles these response formats:
     *   1. Single-function review: metadata has function_name, response has one function change
     *   2. Field-level changes: {"changes": {"fieldName": {"suggested": "value"}}}
     *   3. Legacy single-field: {"hasSuggestion": true, "fieldName": "x", ...}
     */
    processCompletedInference: function(inferenceGR) {
        var response = '' + inferenceGR.u_response;
        var targetTable = '' + inferenceGR.u_table;
        var targetSysId = '' + inferenceGR.u_target;
        var metadata = '' + inferenceGR.u_metadata;

        // Extract agent_id and function_name from metadata (stored as flat JSON)
        var agentId = '';
        var functionName = '';
        if (metadata) {
            try {
                var meta = JSON.parse(metadata);
                agentId = meta.agent_id || '';
                functionName = meta.function_name || '';
            } catch (e) {
                gs.warn('PulseBox: Could not parse metadata: ' + metadata);
            }
        }
        if (!agentId) {
            var agentGR = new GlideRecord('u_ai_agent');
            agentGR.addQuery('u_target_table', targetTable);
            agentGR.addQuery('u_active', true);
            agentGR.setLimit(1);
            agentGR.query();
            if (agentGR.next()) agentId = agentGR.getUniqueValue();
        }
        if (!agentId) return;

        try {
            // Clean up markdown code fences if present
            var cleanResponse = response.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

            // Handle ECC error prefix - find the JSON start
            var jsonStart = cleanResponse.indexOf('{');
            if (jsonStart > 0) {
                cleanResponse = cleanResponse.substring(jsonStart);
            }

            var parsed = JSON.parse(cleanResponse);

            // Check if there are changes
            if (!parsed.hasChanges && !parsed.hasSuggestion) return;

            var fileGR = new GlideRecord('u_ai_file');
            fileGR.initialize();
            fileGR.u_agent = agentId;
            fileGR.u_target_table = targetTable;
            fileGR.u_target_sys_id = targetSysId;
            fileGR.u_status = 'pending';

            if (functionName && parsed.changes) {
                // Single-function review: store as function-level change
                fileGR.u_field_name = 'script:' + functionName;
                fileGR.u_changes = JSON.stringify(parsed.changes);
                fileGR.u_explanation = parsed.summary || '';
            } else if (parsed.changes) {
                // Field-level changes
                fileGR.u_changes = JSON.stringify(parsed.changes);
                fileGR.u_explanation = parsed.summary || '';
            } else {
                // Legacy single-field format
                fileGR.u_field_name = parsed.fieldName || '';
                fileGR.u_suggested_content = parsed.suggestedContent || '';
                fileGR.u_explanation = parsed.explanation || '';
            }

            fileGR.insert();
            gs.info('PulseBox: Created review for ' + targetTable + '/' + targetSysId + (functionName ? ' func=' + functionName : ''));
        } catch (e) {
            gs.error('PulseBox: Error parsing response: ' + e + '\nResponse: ' + response.substring(0, 500));
        }
    },

    /**
     * Build context string for a record to send to the LLM
     */
    buildRecordContext: function(gr, tableName) {
        var context = 'Table: ' + tableName + '\nSys ID: ' + gr.getUniqueValue() + '\n\n';
        var refFields = ['caller_id', 'assigned_to', 'opened_by', 'resolved_by', 'state', 'priority'];
        var fields = this.getRelevantFields(gr, tableName);
        for (var i = 0; i < fields.length; i++) {
            var field = fields[i];
            var value = (refFields.indexOf(field) >= 0) ? gr.getDisplayValue(field) : '' + gr.getValue(field);
            if (value && value !== 'null' && value !== '') context += field + ': ' + value + '\n';
        }
        return context;
    },

    /**
     * Get the relevant fields to include for a given table
     */
    getRelevantFields: function(gr, tableName) {
        if (tableName === 'sys_script_include' || tableName === 'sys_script') return ['name', 'api_name', 'description', 'script', 'active'];
        if (tableName === 'kb_knowledge') return ['short_description', 'text', 'workflow_state'];
        if (tableName === 'incident') return ['number', 'short_description', 'description', 'caller_id', 'assigned_to', 'state', 'priority', 'comments'];
        return ['name', 'short_description', 'description'];
    },

    type: 'PulseBoxAIAB'
});
